/**
 * @name XSS via URL construction
 * @description URL construction with user input could lead to Cross-Site Scripting
 * @kind path-problem
 * @problem.severity high
 * @id py/xss-url
 * @tags security
 *        external/cwe/cwe-079
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module XssConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for URL construction that could be used in HTML contexts
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("yarl").getMember("URL").getACall() and
      sink = call.getArg(0)
    )
    or
    // Look for URL string conversion that could be embedded in HTML
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("str").getACall() and
      exists(DataFlow::CallCfgNode urlCall |
        urlCall = API::moduleImport("yarl").getMember("URL").getACall() and
        call.getArg(0) = urlCall
      ) and
      sink = call
    )
  }
}

module XssFlow = TaintTracking::Global<XssConfig>;
import XssFlow::PathGraph

from XssFlow::PathNode source, XssFlow::PathNode sink
where XssFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "XSS potential: user input flows into URL construction that could be embedded in HTML $@.", source.getNode(), "user input"
